        long long mult(long long a, long long b) {
            long long res = a * b;
            long long m = modulus();
            return ((res % m) + m) % m;
        }

        long long add(long long a, long long b) {
            long long m = modulus();
            long long res = a + b;
            return res >= m ? res - m : res;
        }

        long long subtract(long long a, long long b) {
            long long m = modulus();
            long long res = a - b;
            return res < 0 ? res + m : res;
        }

        long long ncr(int n, int r) {
            // Implement nCr with precomputed factorials or direct calculation
            // For simplicity, assume small n and r
            long long res = 1;
            for (int i = 1; i <= r; ++i) {
                res = mult(res, n - i + 1);
                res = mult(res, smallInv(i));
            }
            return res;
        }

        long long smallInv(int n) {
            // Modular inverse using Fermat's little theorem
            return pow_mod(n, modulus() - 2);
        }

        long long pow_mod(long long base, long long exp) {
            long long result = 1;
            long long m = modulus();
            base %= m;
            while (exp > 0) {
                if (exp & 1) result = (result * base) % m;
                base = (base * base) % m;
                exp >>= 1;
            }
            return result;
        }
    };
};

